function unwrapFileDescriptorSetBase64(encoded: string): string {
  const bytes = Buffer.from(encoded, "base64");
  if (bytes[0] !== 0x0a) {
    return encoded;
  }
  let offset = 1;
  let shift = 0;
  let length = 0;
  while (offset < bytes.length) {
    const byte = bytes[offset++];
    length |= (byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) {
      break;
    }
    shift += 7;
  }
  if (length <= 0 || offset + length > bytes.length) {
    return encoded;
  }
  return Buffer.from(bytes.subarray(offset, offset + length)).toString("base64");
}

const file_verter_v1_component_meta = fileDesc(
  unwrapFileDescriptorSetBase64(componentMetaDescriptorParts.join("")),
);

export const ComponentMetaPayloadSchema = messageDesc<ComponentMetaPayload>(
  file_verter_v1_component_meta,
  0,
);

export type ComponentMetaPayloadInit = MessageInitShape<typeof ComponentMetaPayloadSchema>;

const SCHEMA_VERSION = 1;
const PRIMITIVE_STRING = 1;
const PRIMITIVE_UNDEFINED = 11;
const OBJECT_MEMBER_PROPERTY = 1;
const ACCEPTED_SURFACE_COMPLETENESS_EXACT = 1;
const ROOT_REACHABILITY_NO_FALLTHROUGH = 1;
const FALLTHROUGH_SURFACE_NONE = 1;
const NO_FALLTHROUGH_REASON_NO_TEMPLATE = 5;

function typeNode(caseName: string, value: Record<string, unknown>) {
  return {
    kind: {
      case: caseName,
      value,
    },
  };
}

